#include<bits/stdc++.h>
#define int long long
using namespace std;
vector<int>v[111111];
int f[111111],a[111111],d[111111];
int dp[555555][22];
int mf[111111];
void dfs(int p,int g,int fa){
	dp[p][0]=fa;
	d[p]=g;
	for(int i=1;i<=20;i++){
		dp[p][i]=dp[dp[p][i-1]][i-1];
	}
	mf[p]=max(mf[fa],p);
	for(int i=0;i<v[p].size();i++){
		if(v[p][i]!=fa){
			f[v[p][i]]=p;
			dfs(v[p][i],g+1,p);
		}
	}
}
int lca(int x,int y){
	if(d[x]<d[y]){
		swap(x,y);
	}
	for(int i=20;i>=0;i--){
		if(d[dp[x][i]]>=d[y]){
			x=dp[x][i];
		}
	}
	if(x==y){
		return x;
	}
	for(int i=20;i>=0;i--){
		if(dp[x][i]!=dp[y][i]){
			x=dp[x][i];
			y=dp[y][i];
		}
	}    
	return dp[x][0];
}
signed main(){
	ios::sync_with_stdio(0);cin.tie(0);cout.tie(0);
	int n;
	cin>>n;
	for(int i=1;i<n;i++){
		int x;
		cin>>x;
		v[x].push_back(i);
	}
	mf[0]=0;
	dfs(0,0,0);
	int m;
	cin>>m;
	while(m--){
		int g,t;
		cin>>g;
		for(int i=1;i<=g;i++){
			cin>>a[i];
		}
		for(int i=2;i<=g;i++){
			t=lca(a[i-1],a[i]);
			a[i]=t;
		}
		if(g==1){
			cout<<a[1];
			continue;
		}
		cout<<mf[t]<<endl;
	}
    return 0;
}
